insert into public.quests(id,slug) values('e1000000-0000-4000-8000-000000000001','externsteine') on conflict do nothing;
insert into public.quest_versions(id,quest_id,revision,status,approval,field_ready,document) values('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',1,'draft','pending_source_review',false,'{"id":"e1000000-0000-4000-8000-000000000001","versionId":"e2000000-0000-4000-8000-000000000001","revision":1,"title":"Der verlorene Schatz der Externsteine","subtitle":"Vier Steinsiegel. Eine alte Karte. Euer gemeinsames Abenteuer.","story":"Wyldo findet in alten Reiseaufzeichnungen eine Schatzkarte. Gemeinsam mit Runa, dem Steinkauz, sucht ihr vier verlorene Steinsiegel. Ein geheimnisvoller Kristall erinnert euch daran, was einen Schatz wirklich wertvoll macht: Mut, Neugier und gemeinsam erlebte Abenteuer.","region":"Externsteine · Teutoburger Wald","duration":"Noch zu vermessen","distance":"Route noch in Prüfung","difficulty":"Rätsel: leicht bis mittel","ratingSummary":{"average":null,"count":0},"preparation":["Festes Schuhwerk, wettergerechte Kleidung und Trinkwasser.","Geladenes Smartphone; Quest-Inhalte vorab herunterladen.","Auf freigegebenen Wegen bleiben. Keine Felsen besteigen und nichts verstecken oder einsammeln.","Aktuelle Öffnungen und Hinweise des Betreibers vor Ort beachten."],"start":"Noch nicht freigegeben. Vorgeschlagener Ausgangsbereich: Informationszentrum Externsteine.","approval":"pending_source_review","fieldReady":false,"route":[],"routeStatus":"Fünf reale OSM-Orientierungspunkte am 16.10.2026 abgeglichen. Acht Questorte, zusammenhängende Weggeometrie und Begehung sind noch offen. Vor-Ort-Spiel ist noch nicht freigegeben.","stations":[{"title":"Die geheimnisvolle Schatzkarte","place":"Vorschlag: am Informationszentrum","intro":"Wyldo zieht vorsichtig eine zerknitterte Schatzkarte aus seinem Rucksack. „Die habe ich zwischen alten Reiseaufzeichnungen entdeckt! Vier Steinsiegel sollen den Weg zum verlorenen Schatz der Externsteine öffnen. Kommst du mit?“ Auf der Rückseite steht: „Was Wege zeigt, ohne selbst zu gehen, ist unser Anfang.“","success":"","failure":"Wyldo dreht das Papier nachdenklich. „Denk an etwas, das dir unterwegs die Richtung zeigt.“","bridge":"Eine gezeichnete Felsspalte markiert den nächsten Abschnitt. Folgt dem freigegebenen Weg; ihr müsst keine Felsen besteigen.","id":"e3000000-0000-4000-8000-000000000001","order":1,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-1","dialogues":[{"speaker":"Wyldo","text":"Wyldo zieht vorsichtig eine zerknitterte Schatzkarte aus seinem Rucksack. „Die habe ich zwischen alten Reiseaufzeichnungen entdeckt! Vier Steinsiegel sollen den Weg zum verlorenen Schatz der Externsteine öffnen. Kommst du mit?“ Auf der Rückseite steht: „Was Wege zeigt, ohne selbst zu gehen, ist unser Anfang.“","mood":"talk"}],"puzzle":{"kind":"text","prompt":"Löse das Kartenrätsel: Was zeigt Wege und Orte, ohne selbst zu gehen? Ein Wort genügt.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}},{"title":"Das erste Steinsiegel","place":"Vorschlag: Weg mit Blick auf die Felsen","intro":"Im Abenteuer erscheinen drei Zeichen auf einem Felsen der Schatzkarte: Kreis, Dreieck, Kreis, Dreieck, Kreis. Wyldo bleibt auf dem Weg stehen. „Mut heißt nicht, überall hinzuklettern. Mut heißt auch, den sicheren Weg zu wählen.“","success":"","failure":"Das Zeichen bleibt dunkel. „Schau auf die ganze Reihe und suche einen Wechsel“, schlägt Wyldo vor.","bridge":"Zwischen den gezeichneten Bäumen und Felsen auf eurer Karte versteckt sich eine neue Verbindung. Ihr könnt sie gemeinsam entschlüsseln.","id":"e3000000-0000-4000-8000-000000000002","order":2,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Mut","imageAsset":"station-2","dialogues":[{"speaker":"Wyldo","text":"Im Abenteuer erscheinen drei Zeichen auf einem Felsen der Schatzkarte: Kreis, Dreieck, Kreis, Dreieck, Kreis. Wyldo bleibt auf dem Weg stehen. „Mut heißt nicht, überall hinzuklettern. Mut heißt auch, den sicheren Weg zu wählen.“","mood":"talk"}],"puzzle":{"kind":"choice","prompt":"Beobachte die Zeichen auf der digitalen Karte: Kreis · Dreieck · Kreis · Dreieck · Kreis. Welches Zeichen folgt?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"kreis","label":"Kreis"},{"id":"dreieck","label":"Dreieck"},{"id":"quadrat","label":"Quadrat"}]}},{"title":"Die Zeichen der Natur","place":"Vorschlag: Abschnitt am Waldrand","intro":"Wyldo vergleicht die kleinen Zeichnungen auf der Schatzkarte. Unter einem Baum steht Holz. Unter einem Felsen fehlt das Wort. „Die Karte beschreibt, woraus die Dinge bestehen. Welches Wort gehört zum Felsen?“ Ihr löst das Rätsel auf dem Bildschirm; Pflanzen und Felsen bleiben unberührt.","success":"","failure":"Wyldo zeigt noch einmal auf die beiden Paare. „Der Baum liefert Holz. Woraus besteht ein Felsen?“","bridge":"Runa spricht langsam und deutlich. Ihre Botschaft kannst du hören oder vollständig lesen.","id":"e3000000-0000-4000-8000-000000000003","order":3,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Neugier","imageAsset":"station-3","dialogues":[{"speaker":"Wyldo","text":"Wyldo vergleicht die kleinen Zeichnungen auf der Schatzkarte. Unter einem Baum steht Holz. Unter einem Felsen fehlt das Wort. „Die Karte beschreibt, woraus die Dinge bestehen. Welches Wort gehört zum Felsen?“ Ihr löst das Rätsel auf dem Bildschirm; Pflanzen und Felsen bleiben unberührt.","mood":"think"}],"puzzle":{"kind":"text","prompt":"Ergänze das Paar: Baum → Holz, Fels → …","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}},{"title":"Das Geheimnis des Wassers","place":"Vorschlag: ruhiger Abschnitt am Weg","intro":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","success":"","failure":"Runa wiederholt geduldig die Botschaft. „Zähle die Wörter von vorn; gesucht ist Nummer zwei.“","bridge":"Die Karte zeigt nun vier verstreute Wörter. Gemeinsam müsst ihr daraus eine verständliche Botschaft machen.","id":"e3000000-0000-4000-8000-000000000004","order":4,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Zuhören","imageAsset":"station-4","dialogues":[{"speaker":"Runa","text":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","mood":"talk"}],"puzzle":{"kind":"listen","prompt":"Höre die Botschaft oder lies sie unten. Welches Wort nennt Runa als Zweites?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"transcript":"Runa sagt langsam: „Blatt. Wasser. Stein. Wind. Merkt euch das zweite Wort, dann findet ihr das Siegel des Zuhörens.“"}},{"title":"Runa, der Steinkauz","place":"Vorschlag: breiter Wegabschnitt","intro":"Runa, der Steinkauz, landet in der erfundenen Geschichte neben Wyldos Karte. „Ihr habt gut zugehört. Nun fehlt noch das Siegel der Gemeinschaft.“ Wyldo legt vier Wortkarten aus. „Wir schaffen es zusammen – auch wenn du allein unterwegs bist, gehören Runa und ich zu deinem Team.“","success":"","failure":"Die Wörter ergeben noch nicht den Satz auf der Karte. „Fangt mit Gemeinsam an und probiert es noch einmal“, sagt Wyldo.","bridge":"Vier Siegel liegen vor euch. Ihre Reihenfolge wird zum Schlüssel für das nächste Rätsel.","id":"e3000000-0000-4000-8000-000000000005","order":5,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Gemeinschaft","imageAsset":"station-5","dialogues":[{"speaker":"Runa","text":"Runa, der Steinkauz, landet in der erfundenen Geschichte neben Wyldos Karte. „Ihr habt gut zugehört. Nun fehlt noch das Siegel der Gemeinschaft.“ Wyldo legt vier Wortkarten aus. „Wir schaffen es zusammen – auch wenn du allein unterwegs bist, gehören Runa und ich zu deinem Team.“","mood":"talk"}],"puzzle":{"kind":"order","prompt":"Tippe die Wortkarten in dieser Reihenfolge an: Gemeinsam kommen wir weiter. Mit „Reihenfolge löschen“ kannst du neu beginnen.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"wir","label":"wir"},{"id":"weiter","label":"weiter"},{"id":"gemeinsam","label":"Gemeinsam"},{"id":"kommen","label":"kommen"}]}},{"title":"Die verschwundenen Spuren","place":"Vorschlag: Weg in Richtung Ausgangspunkt","intro":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","success":"","failure":"Wyldo vergleicht die Zeichen. „Die Reihenfolge unserer Reise ist der Schlüssel. Schau in deinen Siegelbeutel.“","bridge":"Hinter der digitalen Tür liegt eine letzte Frage: Was darf man von diesem Ort mitnehmen?","id":"e3000000-0000-4000-8000-000000000006","order":6,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-6","dialogues":[{"speaker":"Wyldo","text":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","mood":"talk"}],"puzzle":{"kind":"code","prompt":"Setze die vier Zahlen in der Reihenfolge zusammen, in der du die Siegel erhalten hast. Gib den vierstelligen Code ein.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}},{"title":"Das letzte Geheimnis der Felsen","place":"Vorschlag: Rückweg auf ausgeschildertem Weg","intro":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","success":"","failure":"„Unser Schatz braucht keine echten Fundstücke“, erinnert Runa. „Bleib auf dem Weg und lass die Natur an ihrem Platz.“","bridge":"Im Finale treffen alle vier Siegel aufeinander. Ihr bleibt an einem sicheren Platz auf dem Weg.","id":"e3000000-0000-4000-8000-000000000007","order":7,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-7","dialogues":[{"speaker":"Runa","text":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","mood":"talk"}],"puzzle":{"kind":"choice","prompt":"Was gehört in deinen Rucksack, wenn du nach Hause gehst?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"erinnerung","label":"Erinnerungen und meinen eigenen Abfall."},{"id":"moos","label":"Moos und ein Stück Fels als Andenken."},{"id":"fund","label":"Ein versteckter Gegenstand, den ich abseits des Weges suche."}]}},{"title":"Die verborgene Schatztruhe","place":"Vorschlag: Abschluss nahe dem Ausgangspunkt","intro":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","success":"","failure":"Wyldo lächelt. „Denk an unsere gemeinsame Reise. Wie nennen wir solche Erlebnisse?“","bridge":"Die Geschichte endet hier. Macht euch auf einem freigegebenen Weg sicher auf den Rückweg.","id":"e3000000-0000-4000-8000-000000000008","order":8,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-8","dialogues":[{"speaker":"Wyldo","text":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","mood":"surprise"}],"puzzle":{"kind":"text","prompt":"Vervollständige die Botschaft: Mut, Neugier und gemeinsam erlebte …","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}],"assets":[{"id":"station-1","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-2","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-3","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-4","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-5","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-6","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-7","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"station-8","kind":"image","url":null,"bundled":"scenes","description":"Zum freigegebenen Mockup ergänzte Abenteuerillustration; kein Ortsfoto"},{"id":"wyldo-poses","kind":"image","url":null,"bundled":"fox","description":"Vier Gesamtposen nach der bereitgestellten Wyldo-Vorlage; kein Character-Rig"},{"id":"stone-seals","kind":"image","url":null,"description":"Vier digitale Steinsiegel für Mut, Neugier, Zuhören und Gemeinschaft.","bundled":"seals"}],"badge":{"name":"Hüter der Externsteine","description":"Alle acht Stationen abgeschlossen und vier Steinsiegel vereint."},"ending":"Der Kristall bewahrt eure Geschichte. Wyldo steckt die alte Karte wieder ein: „Der größte Schatz war, dass wir gemeinsam losgegangen sind.“ Runa begleitet euch noch ein Stück. In der Natur bleibt alles an seinem Platz; eure Siegel und Erinnerungen nehmt ihr digital mit."}'::jsonb) on conflict(id) do update set document=excluded.document where quest_versions.status='draft';
