insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000002','Das Dreieck leuchtet auf. Das erste Steinsiegel erscheint in eurem digitalen Beutel: Mut. „Wir kommen auch ohne riskante Abkürzung voran“, sagt Wyldo.','["Es wechseln sich immer genau zwei Zeichen ab.","Nach einem Kreis folgt in dieser Reihe ein Dreieck."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
