insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000003','e2000000-0000-4000-8000-000000000001',3,'Die Zeichen der Natur',null,null,40,'unverified','Neugier','{"title":"Die Zeichen der Natur","place":"Vorschlag: Abschnitt am Waldrand","intro":"Wyldo vergleicht die kleinen Zeichnungen auf der Schatzkarte. Unter einem Baum steht Holz. Unter einem Felsen fehlt das Wort. „Die Karte beschreibt, woraus die Dinge bestehen. Welches Wort gehört zum Felsen?“ Ihr löst das Rätsel auf dem Bildschirm; Pflanzen und Felsen bleiben unberührt.","success":"","failure":"Wyldo zeigt noch einmal auf die beiden Paare. „Der Baum liefert Holz. Woraus besteht ein Felsen?“","bridge":"Runa spricht langsam und deutlich. Ihre Botschaft kannst du hören oder vollständig lesen.","id":"e3000000-0000-4000-8000-000000000003","order":3,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Neugier","imageAsset":"station-3","dialogues":[{"speaker":"Wyldo","text":"Wyldo vergleicht die kleinen Zeichnungen auf der Schatzkarte. Unter einem Baum steht Holz. Unter einem Felsen fehlt das Wort. „Die Karte beschreibt, woraus die Dinge bestehen. Welches Wort gehört zum Felsen?“ Ihr löst das Rätsel auf dem Bildschirm; Pflanzen und Felsen bleiben unberührt.","mood":"think"}],"puzzle":{"kind":"text","prompt":"Ergänze das Paar: Baum → Holz, Fels → …","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000003','text','Ergänze das Paar: Baum → Holz, Fels → …','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000003','„Stein!“, sagt Wyldo. „Du hast die Verbindung erkannt.“ Das Siegel der Neugier leuchtet auf. Zwischen den Bäumen hört ihr einen Ruf: Runa, der Steinkauz, möchte euch eine Botschaft mitgeben.','["Gesucht ist das Material eines Felsens.","Das gesuchte Wort hat fünf Buchstaben und lautet Stein."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000003',array['stein','gestein']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000003-0','e3000000-0000-4000-8000-000000000003','arrival',0,'Wyldo','Wyldo vergleicht die kleinen Zeichnungen auf der Schatzkarte. Unter einem Baum steht Holz. Unter einem Felsen fehlt das Wort. „Die Karte beschreibt, woraus die Dinge bestehen. Welches Wort gehört zum Felsen?“ Ihr löst das Rätsel auf dem Bildschirm; Pflanzen und Felsen bleiben unberührt.','think') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000004','e2000000-0000-4000-8000-000000000001',4,'Das Geheimnis des Wassers',null,null,40,'unverified','Zuhören','{"title":"Das Geheimnis des Wassers","place":"Vorschlag: ruhiger Abschnitt am Weg","intro":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","success":"","failure":"Runa wiederholt geduldig die Botschaft. „Zähle die Wörter von vorn; gesucht ist Nummer zwei.“","bridge":"Die Karte zeigt nun vier verstreute Wörter. Gemeinsam müsst ihr daraus eine verständliche Botschaft machen.","id":"e3000000-0000-4000-8000-000000000004","order":4,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Zuhören","imageAsset":"station-4","dialogues":[{"speaker":"Runa","text":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","mood":"talk"}],"puzzle":{"kind":"listen","prompt":"Höre die Botschaft oder lies sie unten. Welches Wort nennt Runa als Zweites?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"transcript":"Runa sagt langsam: „Blatt. Wasser. Stein. Wind. Merkt euch das zweite Wort, dann findet ihr das Siegel des Zuhörens.“"}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000004','listen','Höre die Botschaft oder lies sie unten. Welches Wort nennt Runa als Zweites?','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,'Runa sagt langsam: „Blatt. Wasser. Stein. Wind. Merkt euch das zweite Wort, dann findet ihr das Siegel des Zuhörens.“') on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000004','„Wasser“, wiederholt Wyldo. Runa neigt den Kopf. Das dritte Steinsiegel heißt Zuhören. Auch wer die Textalternative gelesen hat, erhält dasselbe Siegel.','["Die Botschaft enthält vier Naturwörter. Zähle ab dem ersten Wort.","Nach „Blatt“ und vor „Stein“ steht das gesuchte Wort."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000004',array['wasser']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000004-0','e3000000-0000-4000-8000-000000000004','arrival',0,'Runa','„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000005','e2000000-0000-4000-8000-000000000001',5,'Runa, der Steinkauz',null,null,40,'unverified','Gemeinschaft','{"title":"Runa, der Steinkauz","place":"Vorschlag: breiter Wegabschnitt","intro":"Runa, der Steinkauz, landet in der erfundenen Geschichte neben Wyldos Karte. „Ihr habt gut zugehört. Nun fehlt noch das Siegel der Gemeinschaft.“ Wyldo legt vier Wortkarten aus. „Wir schaffen es zusammen – auch wenn du allein unterwegs bist, gehören Runa und ich zu deinem Team.“","success":"","failure":"Die Wörter ergeben noch nicht den Satz auf der Karte. „Fangt mit Gemeinsam an und probiert es noch einmal“, sagt Wyldo.","bridge":"Vier Siegel liegen vor euch. Ihre Reihenfolge wird zum Schlüssel für das nächste Rätsel.","id":"e3000000-0000-4000-8000-000000000005","order":5,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Gemeinschaft","imageAsset":"station-5","dialogues":[{"speaker":"Runa","text":"Runa, der Steinkauz, landet in der erfundenen Geschichte neben Wyldos Karte. „Ihr habt gut zugehört. Nun fehlt noch das Siegel der Gemeinschaft.“ Wyldo legt vier Wortkarten aus. „Wir schaffen es zusammen – auch wenn du allein unterwegs bist, gehören Runa und ich zu deinem Team.“","mood":"talk"}],"puzzle":{"kind":"order","prompt":"Tippe die Wortkarten in dieser Reihenfolge an: Gemeinsam kommen wir weiter. Mit „Reihenfolge löschen“ kannst du neu beginnen.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"wir","label":"wir"},{"id":"weiter","label":"weiter"},{"id":"gemeinsam","label":"Gemeinsam"},{"id":"kommen","label":"kommen"}]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000005','order','Tippe die Wortkarten in dieser Reihenfolge an: Gemeinsam kommen wir weiter. Mit „Reihenfolge löschen“ kannst du neu beginnen.','[{"id":"wir","label":"wir"},{"id":"weiter","label":"weiter"},{"id":"gemeinsam","label":"Gemeinsam"},{"id":"kommen","label":"kommen"}]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000005','„Gemeinsam kommen wir weiter!“ Der Satz bringt das vierte Siegel zum Leuchten: Gemeinschaft. Wyldo schaut zu Runa. „Jetzt fehlt uns nur noch der Zugang zum Kristall.“','["Der Satz beginnt mit „Gemeinsam“.","Danach folgen „kommen“, „wir“ und „weiter“."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000005',array['gemeinsam,kommen,wir,weiter']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000005-0','e3000000-0000-4000-8000-000000000005','arrival',0,'Runa','Runa, der Steinkauz, landet in der erfundenen Geschichte neben Wyldos Karte. „Ihr habt gut zugehört. Nun fehlt noch das Siegel der Gemeinschaft.“ Wyldo legt vier Wortkarten aus. „Wir schaffen es zusammen – auch wenn du allein unterwegs bist, gehören Runa und ich zu deinem Team.“','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000006','e2000000-0000-4000-8000-000000000001',6,'Die verschwundenen Spuren',null,null,40,'unverified',null,'{"title":"Die verschwundenen Spuren","place":"Vorschlag: Weg in Richtung Ausgangspunkt","intro":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","success":"","failure":"Wyldo vergleicht die Zeichen. „Die Reihenfolge unserer Reise ist der Schlüssel. Schau in deinen Siegelbeutel.“","bridge":"Hinter der digitalen Tür liegt eine letzte Frage: Was darf man von diesem Ort mitnehmen?","id":"e3000000-0000-4000-8000-000000000006","order":6,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-6","dialogues":[{"speaker":"Wyldo","text":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","mood":"talk"}],"puzzle":{"kind":"code","prompt":"Setze die vier Zahlen in der Reihenfolge zusammen, in der du die Siegel erhalten hast. Gib den vierstelligen Code ein.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000006','code','Setze die vier Zahlen in der Reihenfolge zusammen, in der du die Siegel erhalten hast. Gib den vierstelligen Code ein.','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000006','Mit 2413 öffnet sich auf dem Bildschirm eine steinerne Tür. Niemand muss eine echte Tür suchen oder einen abgesperrten Bereich betreten.','["Beginne mit Mut und Neugier. Ihre Zahlen sind 2 und 4.","Die ganze Reihenfolge lautet: Mut 2, Neugier 4, Zuhören 1, Gemeinschaft 3."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000006',array['2413']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000006-0','e3000000-0000-4000-8000-000000000006','arrival',0,'Wyldo','Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000007','e2000000-0000-4000-8000-000000000001',7,'Das letzte Geheimnis der Felsen',null,null,40,'unverified',null,'{"title":"Das letzte Geheimnis der Felsen","place":"Vorschlag: Rückweg auf ausgeschildertem Weg","intro":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","success":"","failure":"„Unser Schatz braucht keine echten Fundstücke“, erinnert Runa. „Bleib auf dem Weg und lass die Natur an ihrem Platz.“","bridge":"Im Finale treffen alle vier Siegel aufeinander. Ihr bleibt an einem sicheren Platz auf dem Weg.","id":"e3000000-0000-4000-8000-000000000007","order":7,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-7","dialogues":[{"speaker":"Runa","text":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","mood":"talk"}],"puzzle":{"kind":"choice","prompt":"Was gehört in deinen Rucksack, wenn du nach Hause gehst?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"erinnerung","label":"Erinnerungen und meinen eigenen Abfall."},{"id":"moos","label":"Moos und ein Stück Fels als Andenken."},{"id":"fund","label":"Ein versteckter Gegenstand, den ich abseits des Weges suche."}]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000007','choice','Was gehört in deinen Rucksack, wenn du nach Hause gehst?','[{"id":"erinnerung","label":"Erinnerungen und meinen eigenen Abfall."},{"id":"moos","label":"Moos und ein Stück Fels als Andenken."},{"id":"fund","label":"Ein versteckter Gegenstand, den ich abseits des Weges suche."}]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000007','„Erinnerungen und unseren eigenen Abfall“, bestätigt Wyldo. „Der Ort bleibt so, wie wir ihn vorfinden möchten.“ Runa öffnet ihre Flügel: Der Kristall wartet.','["Im Spiel werden ausschließlich digitale Siegel gesammelt.","Lass Naturmaterialien liegen und nimm deinen eigenen Abfall wieder mit."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000007',array['erinnerung']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000007-0','e3000000-0000-4000-8000-000000000007','arrival',0,'Runa','Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000008','e2000000-0000-4000-8000-000000000001',8,'Die verborgene Schatztruhe',null,null,40,'unverified',null,'{"title":"Die verborgene Schatztruhe","place":"Vorschlag: Abschluss nahe dem Ausgangspunkt","intro":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","success":"","failure":"Wyldo lächelt. „Denk an unsere gemeinsame Reise. Wie nennen wir solche Erlebnisse?“","bridge":"Die Geschichte endet hier. Macht euch auf einem freigegebenen Weg sicher auf den Rückweg.","id":"e3000000-0000-4000-8000-000000000008","order":8,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-8","dialogues":[{"speaker":"Wyldo","text":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","mood":"surprise"}],"puzzle":{"kind":"text","prompt":"Vervollständige die Botschaft: Mut, Neugier und gemeinsam erlebte …","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000008','text','Vervollständige die Botschaft: Mut, Neugier und gemeinsam erlebte …','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000008','Der Kristall erstrahlt. „Abenteuer!“, rufen Wyldo und Runa. Ihr habt alle vier Siegel zusammengebracht und den verlorenen Schatz gefunden.','["Gesucht ist das Wort für besondere Erlebnisse auf einer gemeinsamen Reise.","Der Titel dieses Spiels beschreibt eine Outdoor-Abenteuer-App. Das gesuchte Wort lautet Abenteuer."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000008',array['abenteuer','abenteuer.']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000008-0','e3000000-0000-4000-8000-000000000008','arrival',0,'Wyldo','Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“','surprise') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
